@@ -0,0 +1,76 @@
+import { graphStore, type GraphStore } from "../graph";
+import { attachGraphDevtools } from "./controller";
+import type { GraphDevtoolsChange, GraphDevtoolsEvent } from "./protocol";
+
+/** Deprecated in-process event shape retained by the package root. */
+export type LegacyDevtoolsEvent =
+  | { kind: "upsert"; type: string; id: string; data: Record<string, unknown>; at: string }
+  | { kind: "patch"; type: string; id: string; patch: Record<string, unknown>; at: string }
+  | { kind: "unpatch"; type: string; id: string; keys: string[]; at: string }
+  | { kind: "clearPatch"; type: string; id: string; at: string }
+  | { kind: "list"; key: string; idCount: number; at: string };
+
+type LegacyListener = (event: LegacyDevtoolsEvent) => void;
+
+/** Synthetic events are retained only for the deprecated internal notify seam. */
+const syntheticListeners = new Set<LegacyListener>();
+
+function legacyEventForChange(
+  change: GraphDevtoolsChange,
+  event: GraphDevtoolsEvent,
+  store: GraphStore,
+): LegacyDevtoolsEvent | null {
+  if (event.type !== "mutation") return null;
+  const at = event.observedAt;
+  if (change.category === "entity" && change.id !== undefined && change.action !== "removed") {
+    const data = store.getState().entities[change.key]?.[change.id];
+    return data ? { kind: "upsert", type: change.key, id: change.id, data, at } : null;
+  }
+  if (change.category === "patch" && change.id !== undefined) {
+    const patch = store.getState().patches[change.key]?.[change.id];
+    return patch
+      ? { kind: "patch", type: change.key, id: change.id, patch, at }
+      : { kind: "clearPatch", type: change.key, id: change.id, at };
+  }
+  if (change.category === "list") {
+    return { kind: "list", key: change.key, idCount: change.afterCount ?? 0, at };
+  }
+  return null;
+}
+
+/**
+ * Deprecated default-store observation API. Its source is now the selected
+ * store's v1 controller; no separate history or cursor is maintained.
+ */
+export function subscribeLegacyDevtoolsEvent(
+  listener: LegacyListener,
+  store: GraphStore = graphStore,
+): () => void {
+  const attachment = attachGraphDevtools(store);
+  const controller = attachment.controller;
+  if (!controller) return () => {};
+  syntheticListeners.add(listener);
+  const unsubscribe = controller.subscribe((event) => {
+    if (event.type !== "mutation") return;
+    for (const change of event.payload.changes) {
+      const legacy = legacyEventForChange(change, event, store);
+      if (legacy) listener(legacy);
+    }
+  });
+  return () => {
+    syntheticListeners.delete(listener);
+    unsubscribe();
+    attachment.detach();
+  };
+}
+
+/** @internal Deprecated manual injection used by legacy internal callers. */
+export function emitLegacyDevtoolsEvent(event: LegacyDevtoolsEvent): void {
+  for (const listener of [...syntheticListeners]) {
+    try {
+      listener(event);
+    } catch {
+      // DevTools failures cannot interrupt production graph work.
+    }
+  }
+}
